fn decode_shift(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            // ASCII value of 'a'
            let base = b'a';
            // current letter index 0..25
            let idx = (c as u8) - base;
            // subtract 5 with wraparound
            let decoded_idx = (idx + 26 - 5) % 26;
            // convert back to a char
            (base + decoded_idx) as char
        })
        .collect()
}

fn main() {
    let input: Vec<char> = "afz".chars().collect();
    let output = decode_shift(input);
    let decoded: String = output.into_iter().collect();
    println!("{}", decoded);  // prints "vau"
}